require __DIR__.'/app-bootstrap.php';$token=(string)($_GET['token']??'');$message='The confirmation link is invalid or expired.';if(preg_match('/^[a-f0-9]{64}$/',$token)){try{$st=$pdo->prepare('SELECT * FROM email_change_requests WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1');$st->execute([security_token_hash($token)]);$row=$st->fetch();if($row){$pdo->beginTransaction();$pdo->prepare('UPDATE users SET email=? WHERE id=?')->execute([$row['new_email'],$row['user_id']]);$pdo->prepare('UPDATE email_change_requests SET used_at=NOW() WHERE id=?')->execute([$row['id']]);$pdo->commit();$message='Email address updated. You can now sign in with the new address.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message='The email change could not be completed.';}}layout_header('Confirm email');?><section class="auth panel"><span class="kicker">ACCOUNT SECURITY</span><h1><?=e($message)?></h1><a class="button" href="<?=e(url('login'))?>">Continue to sign in</a></section><?php layout_footer();
